import Foundation

/// Generated by `scripts/gen-buildinfo.sh` before each build.
/// Edit values manually only if running xcodebuild without the script.
enum BuildInfo {
    static let version = "1.5.6"
    static let commit = "f6b18d3"
    static let branch = "move-from-field-below-to"
    static let date = "2026-06-01 19:37 UTC"

    static var shortLabel: String {
        "v\(version) · \(commit)"
    }
}
